DOWNLOAD_SOURCE_OPTIONS = {
    'npm_registry': 'npm', 'pypi_index': 'pypi', 'container_mirror': 'containerMirror', 'ghcr_mirror': 'ghcrMirror',
    'github_proxy_prefix': 'githubAssets', 'github_api_proxy_prefix': 'githubApi',
